#!/usr/bin/env bash
# Generates deploy/k8s/services/<name>/ (Deployment, Service, kustomization) for
# all 20 services from the table below. Safe to run again: same table, same files.
#   bash scripts/gen-k8s-manifests.sh
# To change a service, edit its row here and run the script, do not edit the
# generated files by hand.
set -euo pipefail

cd "$(dirname "$0")/.."
OUT="deploy/k8s/services"
REGISTRY="jurwa-registry:5050"

# name | gRPC port | store (postgres, mongo, redis, none) | database name | addresses it calls
# Store and database: docs/design/database-schema.md section 2.
# Addresses: the *_ADDR variables each service reads in cmd/server/main.go.
SERVICES="
report-submission|9001|mongo|report_submission|
photo-media|9002|mongo|photo_media|
report-history|9003|postgres|report_history|
location-taxonomy|9004|postgres|location_taxonomy|
internal-notes|9005|mongo|internal_notes|
routing-rules|9006|postgres|routing_rules|
routing-engine|9007|none||ROUTING_RULES_ADDR=routing-rules:9006 DEPARTMENT_DIRECTORY_ADDR=department-directory:9008
department-directory|9008|postgres|department_directory|
category-taxonomy|9009|postgres|category_taxonomy|
api-gateway|9010|redis||IDENTITY_ADDR=identity:9016 AUTHORIZATION_ADDR=authorization:9017 CATEGORY_TAXONOMY_ADDR=category-taxonomy:9009 LOCATION_TAXONOMY_ADDR=location-taxonomy:9004 REPORT_SUBMISSION_ADDR=report-submission:9001 INTERNAL_NOTES_ADDR=internal-notes:9005 REPORT_HISTORY_ADDR=report-history:9003 PHOTO_MEDIA_ADDR=photo-media:9002 STATUS_LIFECYCLE_ADDR=status-lifecycle:9011 ANALYTICS_ADDR=analytics:9020 REASSIGNMENT_ADDR=reassignment:9014 DEPARTMENT_DIRECTORY_ADDR=department-directory:9008 NOTIFICATION_ADDR=notification:9018 FEEDBACK_ADDR=feedback:9019
status-lifecycle|9011|postgres|status_lifecycle|
sla-tracking|9012|redis||SLA_POLICY_ADDR=sla-policy:9013
sla-policy|9013|postgres|sla_policy|
reassignment|9014|postgres|reassignment|
audit-log|9015|mongo|audit_log|
identity|9016|postgres|identity|
authorization|9017|postgres|authorization_db|
notification|9018|postgres|notification|
feedback|9019|postgres|feedback|STATUS_LIFECYCLE_ADDR=status-lifecycle:9011
analytics|9020|postgres|analytics|
"

HTTP_PORT=8080 # only api-gateway

secret_env() { # $1 = env name, $2 = key in Secret jurwa-secrets
  cat <<EOF
            - name: $1
              valueFrom:
                secretKeyRef:
                  name: jurwa-secrets
                  key: $2
EOF
}

value_env() { # $1 = env name, $2 = value
  cat <<EOF
            - name: $1
              value: "$2"
EOF
}

write_deployment() { # name port store db
  local name=$1 port=$2 store=$3 db=$4
  local http_port=""
  if [ "$name" = "api-gateway" ]; then
    http_port="
            - name: http
              containerPort: $HTTP_PORT"
  fi

  cat <<EOF
# Generated by scripts/gen-k8s-manifests.sh. Do not edit by hand.
apiVersion: apps/v1
kind: Deployment
metadata:
  name: $name
  labels:
    app.kubernetes.io/name: $name
    app.kubernetes.io/part-of: jurwa
spec:
  replicas: 1
  selector:
    matchLabels:
      app.kubernetes.io/name: $name
  template:
    metadata:
      labels:
        app.kubernetes.io/name: $name
        app.kubernetes.io/part-of: jurwa
    spec:
      # No Jurwa service calls the Kubernetes API, so no service account token is
      # mounted (SonarQube rule: bind to RBAC or disable automounting).
      automountServiceAccountToken: false
      containers:
        - name: $name
          image: $REGISTRY/$name:latest
          imagePullPolicy: Always
          ports:
            - name: grpc
              containerPort: $port$http_port
          envFrom:
            - configMapRef:
                name: $name-config
          # Passwords come from the Secret jurwa-secrets (scripts/create-secrets.sh).
          # \$(VAR) uses a variable defined above it in this list.
          env:
EOF
  secret_env REDIS_PASSWORD redis-password
  value_env REDIS_URL 'redis://:$(REDIS_PASSWORD)@redis:6379/0'
  case "$store" in
    postgres)
      secret_env POSTGRES_USER postgres-user
      secret_env POSTGRES_PASSWORD postgres-password
      value_env DATABASE_URL "postgres://\$(POSTGRES_USER):\$(POSTGRES_PASSWORD)@postgres:5432/$db?sslmode=disable"
      ;;
    mongo)
      secret_env MONGO_USER mongo-user
      secret_env MONGO_PASSWORD mongo-password
      value_env MONGO_URL 'mongodb://$(MONGO_USER):$(MONGO_PASSWORD)@mongo:27017/?authSource=admin'
      ;;
  esac
  if [ "$name" = "identity" ]; then
    secret_env JWT_SECRET jwt-secret
    # Password of the demo accounts (SEED_DEMO_USERS in the ConfigMap).
    secret_env SEED_DEMO_PASSWORD demo-password
  fi
  cat <<EOF
          readinessProbe:
            grpc:
              port: $port
            initialDelaySeconds: 2
            periodSeconds: 5
          livenessProbe:
            grpc:
              port: $port
            initialDelaySeconds: 10
            periodSeconds: 10
            failureThreshold: 3
          resources:
            requests:
              cpu: 50m
              memory: 64Mi
            limits:
              cpu: 250m
              memory: 128Mi
EOF
}

write_service() { # name port
  local name=$1 port=$2
  cat <<EOF
# Generated by scripts/gen-k8s-manifests.sh. Do not edit by hand.
apiVersion: v1
kind: Service
metadata:
  name: $name
  labels:
    app.kubernetes.io/name: $name
    app.kubernetes.io/part-of: jurwa
spec:
  type: ClusterIP
  selector:
    app.kubernetes.io/name: $name
  ports:
    - name: grpc
      port: $port
      targetPort: grpc
      appProtocol: grpc
EOF
  if [ "$name" = "api-gateway" ]; then
    cat <<EOF
    - name: http
      port: $HTTP_PORT
      targetPort: http
EOF
  fi
}

write_kustomization() { # name port store db calls
  local name=$1 port=$2 store=$3 db=$4 calls=$5
  cat <<EOF
# Generated by scripts/gen-k8s-manifests.sh. Do not edit by hand.
apiVersion: kustomize.config.k8s.io/v1beta1
kind: Kustomization
namespace: jurwa

resources:
  - deployment.yaml
  - service.yaml

# Settings without secrets. Kustomize adds a hash to the name, so changing a
# value restarts the pods.
configMapGenerator:
  - name: $name-config
    literals:
      - PORT=$port
      - SERVICE_NAME=$name
      - LOG_LEVEL=info
EOF
  if [ "$name" = "api-gateway" ]; then
    echo "      - HTTP_PORT=$HTTP_PORT"
  fi
  if [ "$store" = "mongo" ]; then
    echo "      - MONGO_DB=$db"
  fi
  if [ "$name" = "identity" ]; then
    # Demo accounts for the roles that cannot register (services/identity/README.md).
    # Local demo cluster only.
    echo "      - SEED_DEMO_USERS=true"
  fi
  for kv in $calls; do
    echo "      - $kv"
  done
}

count=0
while IFS='|' read -r name port store db calls; do
  [ -z "$name" ] && continue
  dir="$OUT/$name"
  mkdir -p "$dir"
  write_deployment "$name" "$port" "$store" "$db" > "$dir/deployment.yaml"
  write_service "$name" "$port" > "$dir/service.yaml"
  write_kustomization "$name" "$port" "$store" "$db" "$calls" > "$dir/kustomization.yaml"
  count=$((count + 1))
done <<< "$SERVICES"

echo "Generated manifests for $count services in $OUT/"
